// 创建全局应用实例
const app = new BatteryHealthApp();

// 页面加载完成后初始化
document.addEventListener('DOMContentLoaded', () => {
    console.log('🚀 电池健康分析应用已加载');
    
    // 更新状态栏时间
    setInterval(() => {
        const timeEl = document.querySelector('.status-time');
        if (timeEl) {
            const now = new Date();
            timeEl.textContent = now.toLocaleTimeString('zh-CN', { 
                hour: '2-digit', 
                minute: '2-digit' 
            });
        }
    }, 1000);
});

// 暴露给 Android WebView 的接口
window.BatteryHealthApp = {
    // 数据回调
    onBatteryData: (data) => {
        if (data) {
            Object.assign(app.currentData.battery, JSON.parse(data));
            app.updateUI();
        }
    },
    
    onDeviceData: (data) => {
        if (data) {
            Object.assign(app.currentData.device, JSON.parse(data));
            app.updateUI();
        }
    },
    
    onChargingData: (data) => {
        if (data) {
            Object.assign(app.currentData.charging, JSON.parse(data));
            app.monitorChargingPower();
        }
    },

    // 导出方法供原生调用
    analyzeBatteryHealth: () => app.analyzeBatteryHealth(),
    parseDeviceConfig: () => app.parseDeviceConfig(),
    analyzePerformance: () => app.analyzePerformance(),
    checkActivationDate: () => app.checkActivationDate(),
    trackTrends: (period) => app.trackTrends(period),
    analyzeBatteryLife: () => app.analyzeBatteryLife(),
    checkBatteryOrigin: () => app.checkBatteryOrigin(),
    monitorChargingPower: () => app.monitorChargingPower(),
    generateWeeklyReport: () => app.generateWeeklyReport(),
    generateMonthlyReport: () => app.generateMonthlyReport(),
    exportReport: (format) => app.exportReport(format),
    shareReport: () => app.shareReport()
};

