        const totalRamMatch = content.match(/Total RAM[:\s]+([\d,]+)\s*K/i) ||
                             content.match(/MemTotal[:\s]+(\d+)\s*kB/i);
        if (totalRamMatch) {
            const kb = parseInt(totalRamMatch[1].replace(/,/g, ''), 10);
            data.totalRam = kb * 1024;
        }
        
        // Free RAM
        const freeRamMatch = content.match(/Free RAM[:\s]+([\d,]+)\s*K/i) ||
                            content.match(/MemFree[:\s]+(\d+)\s*kB/i);
        if (freeRamMatch) {
            const kb = parseInt(freeRamMatch[1].replace(/,/g, ''), 10);
            data.freeRam = kb * 1024;
        }
        
        // Used RAM
        const usedRamMatch = content.match(/Used RAM[:\s]+([\d,]+)\s*K/i);
