        if (acMatch) data.acPowered = acMatch[1].toLowerCase() === 'true';
        
        // USB powered
        const usbMatch = content.match(/USB powered[:\s]+(true|false)/i);
        if (usbMatch) data.usbPowered = usbMatch[1].toLowerCase() === 'true';
        
