// ==================== Data Storage ====================
const Storage = {
    HISTORY_KEY: 'battery_health_history',
    TRENDS_KEY: 'battery_health_trends',
    
    getHistory() {
        try {
            return JSON.parse(localStorage.getItem(this.HISTORY_KEY)) || [];
        } catch {
            return [];
        }
    },
    
    saveHistory(record) {
        const history = this.getHistory();
        history.unshift({
            ...record,
            timestamp: Date.now(),
            id: Date.now().toString(36)
        });
        // Keep only last 50 records
        if (history.length > 50) history.pop();
        localStorage.setItem(this.HISTORY_KEY, JSON.stringify(history));
    },
    
    getTrends() {
        try {
            return JSON.parse(localStorage.getItem(this.TRENDS_KEY)) || [];
        } catch {
            return [];
        }
    },
    
    saveTrend(trend) {
        const trends = this.getTrends();
        trends.push({
            ...trend,
            date: new Date().toISOString().split('T')[0]
        });
        // Keep only last 90 days
        if (trends.length > 90) trends.shift();
        localStorage.setItem(this.TRENDS_KEY, JSON.stringify(trends));
    },
    
    clear() {
        localStorage.removeItem(this.HISTORY_KEY);
        localStorage.removeItem(this.TRENDS_KEY);
    }
};

