        const deviceMatch = content.match(/ro\.product\.device[=:](\w+)/i);
        if (deviceMatch) data.device = deviceMatch[1];
        
        // Android version
        const versionMatch = content.match(/ro\.build\.version\.release[=:]([\d.]+)/i);
        if (versionMatch) data.androidVersion = versionMatch[1];
        
        // Security patch
        const patchMatch = content.match(/ro\.build\.version\.security_patch[=:]([\d-]+)/i);
