        // Total battery drain
        const drainMatch = content.match(/Total battery drain[:\s]+([\d.]+%)\s*-\s*([\d.]+\s*mAh)/i);
        if (drainMatch) {
            data.totalDrain = {
                percentage: drainMatch[1],
                mah: drainMatch[2]
            };
        }
        
        // Estimated battery life (calculate based on drain rate)
        if (data.totalDrain && data.totalDrain.percentage) {
            const drainPercent = parseFloat(data.totalDrain.percentage);
            if (drainPercent > 0) {
                const hours = (100 / drainPercent) * 24; // Assuming 24h period
                data.estimatedLife = Math.round(hours);
            }
        }
        
        return data;
