        // Temperature (divide by 10 for Celsius)
        const tempMatch = content.match(/(?:^|\n).*temperature[:\s]+(-?\d+)/i);
        if (tempMatch) {
            data.temperature = parseInt(tempMatch[1], 10) / 10;
        }
        
        // Status
        const statusMatch = content.match(/(?:^|\n).*status[:\s]+(\w+)/i);
        if (statusMatch) {
            data.status = statusMatch[1];
        }
        
        // Health
        const healthMatch = content.match(/(?:^|\n).*health[:\s]+(\w+)/i);
        if (healthMatch) {
            data.health = healthMatch[1];
        }
        
        // Technology
        const techMatch = content.match(/technology[:\s]+(\w+)/i);
        if (techMatch) {
            data.technology = techMatch[1];
        }
        
        // Cycle count
        const cycleMatch = content.match(/cycle count[:\s]+(\d+)/i);
        if (cycleMatch) {
            data.cycleCount = parseInt(cycleMatch[1], 10);
        }
        
        // Battery level
        const levelMatch = content.match(/level[:\s]+(\d+)/i);
        if (levelMatch) {
            data.level = parseInt(levelMatch[1], 10);
        }
        
        // Scale
        const scaleMatch = content.match(/scale[:\s]+(\d+)/i);
        if (scaleMatch) {
            data.scale = parseInt(scaleMatch[1], 10);
        }
        
        return data;
