    /**
     * Parse performance data from dumpsys meminfo and cpuinfo
     */
    parsePerformanceData(content) {
        const data = {
            totalRam: null,
            freeRam: null,
            usedRam: null,
            cachedRam: null,
            cpuUsage: null,
            topProcesses: []
        };
        
        // Total RAM
        const totalRamMatch = content.match(/Total RAM[:\s]+([\d,]+)\s*K/i) ||
                             content.match(/MemTotal[:\s]+(\d+)\s*kB/i);
        if (totalRamMatch) {
            const kb = parseInt(totalRamMatch[1].replace(/,/g, ''), 10);
            data.totalRam = kb * 1024;
        }
        
        // Free RAM
        const freeRamMatch = content.match(/Free RAM[:\s]+([\d,]+)\s*K/i) ||
                            content.match(/MemFree[:\s]+(\d+)\s*kB/i);
        if (freeRamMatch) {
            const kb = parseInt(freeRamMatch[1].replace(/,/g, ''), 10);
            data.freeRam = kb * 1024;
        }
        
        // Used RAM
        const usedRamMatch = content.match(/Used RAM[:\s]+([\d,]+)\s*K/i);
        if (usedRamMatch) {
            const kb = parseInt(usedRamMatch[1].replace(/,/g, ''), 10);
            data.usedRam = kb * 1024;
        }
        
        // Cached RAM
        const cachedMatch = content.match(/Cached RAM[:\s]+([\d,]+)\s*K/i) ||
                           content.match(/Cached[:\s]+(\d+)\s*kB/i);
        if (cachedMatch) {
            const kb = parseInt(cachedMatch[1].replace(/,/g, ''), 10);
            data.cachedRam = kb * 1024;
        }
        
        // CPU usage
        const cpuMatch = content.match(/CPU:\s*(\d+)%/i) ||
                        content.match(/(\d+)%\s*TOTAL/i);
        if (cpuMatch) data.cpuUsage = parseInt(cpuMatch[1], 10);
        
        // Top processes
        const processMatches = content.matchAll(/(\d+)%\s+\d+\/\w+[:\s]+([\w.]+)/g);
        for (const match of processMatches) {
            if (data.topProcesses.length < 5) {
                data.topProcesses.push({
                    usage: parseInt(match[1], 10),
                    name: match[2]
                });
            }
        }
        
        return data;
    },
    
    /**
     * Parse battery life data from dumpsys batterystats
     */
    parseBatteryLife(content) {
        const data = {
            screenOnTime: null,
            screenOffTime: null,
            totalDrain: null,
            estimatedLife: null,
            idleDrain: null
        };
        
        // Screen on time
        const screenOnMatch = content.match(/Screen on[:\s]+([\d\w\s]+?)(?:\n|$)/i) ||
                             content.match(/Screen on time[:\s]+([\d\w\s]+?)(?:\n|$)/i);
        if (screenOnMatch) data.screenOnTime = screenOnMatch[1].trim();
        
        // Total battery drain
        const drainMatch = content.match(/Total battery drain[:\s]+([\d.]+%)\s*-\s*([\d.]+\s*mAh)/i);
        if (drainMatch) {
            data.totalDrain = {
                percentage: drainMatch[1],
                mah: drainMatch[2]
            };
        }
        
        // Estimated battery life (calculate based on drain rate)
        if (data.totalDrain && data.totalDrain.percentage) {
            const drainPercent = parseFloat(data.totalDrain.percentage);
            if (drainPercent > 0) {
                const hours = (100 / drainPercent) * 24; // Assuming 24h period
                data.estimatedLife = Math.round(hours);
            }
        }
        
        return data;
    },
    
    /**
     * Parse app usage from batterystats
     */
    parseAppUsage(content) {
        const apps = [];
        
        // Pattern for app usage: percentage, mAh, package name
        const appPattern = /([\d.]+)%\s+([\d.]+\s*mAh)\s+([\w.]+)/g;
        let match;
        
        while ((match = appPattern.exec(content)) !== null) {
            // Skip system processes
            if (match[3].startsWith('android') || match[3].startsWith('com.android')) {
                continue;
            }
            
            apps.push({
                percentage: parseFloat(match[1]),
                consumption: match[2],
                packageName: match[3],
                name: this.getAppName(match[3])
            });
            
            if (apps.length >= 10) break;
        }
        
        // Sort by percentage descending
        return apps.sort((a, b) => b.percentage - a.percentage);
    },
    
